const EN_BASE: Record<string, string> = { ...EN };
/** v1.10: переводы модов (locale/en.json) поверх встроенных; пустой объект — только встроенные */
export function setModTranslations(m: Record<string, string>) {
  for (const k of Object.keys(EN)) delete EN[k];
  Object.assign(EN, EN_BASE); for (const k in m) if (/[А-Яа-яЁё]/.test(k) && typeof m[k] === 'string' && !(k in EN_BASE)) EN[k] = m[k];
  RE = null; cache.clear();
}
let RE: RegExp | null = null;
function build() {
  const cyr = /[А-Яа-яЁё]/;
  const alt = Object.keys(EN).sort((a, b) => b.length - a.length).map(k => (cyr.test(k[0]) ? '(?<![А-Яа-яЁё])' : '') + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + (cyr.test(k[k.length - 1]) ? '(?![А-Яа-яЁё])' : ''));
  RE = new RegExp(alt.join('|'), 'g');
}
const cache = new Map<string, string>();
/** Перевести строку (HTML или текст) на текущий язык */
export function tr(s: string): string {
  if (LANG === 'ru' || !s || !/[А-Яа-яЁё]/.test(s)) return s;
  const c = cache.get(s); if (c !== undefined) return c;
  if (!RE) build();
  let r = s.replace(RE!, m => EN[m] ?? m);
  r = r.replace(/(\d)\s?с(?![А-Яа-яЁё])/g, '$1 s').replace(/(\d)\s?ч(?![А-Яа-яЁё])/g, '$1 h').replace(/(\d)\s?шт(?![А-Яа-яЁё])/g, '$1 pcs').replace(/(?<![А-Яа-яЁё])с…/g, 's…');
  r = r.replace(/«/g, '“').replace(/»/g, '”');
  if (cache.size > 4000) cache.clear(); cache.set(s, r); return r;
}
export function setLang(l: Lang) { LANG = l === 'en' ? 'en' : 'ru'; cache.clear(); if (typeof document !== 'undefined') document.documentElement.lang = LANG; }
/** Для тестов: найти непереведённые фрагменты */
export function untranslated(s: string): string[] { const t = tr(s); return (t.match(/[А-Яа-яЁё][А-Яа-яЁё\s«».,:—-]*/g) || []).map(x => x.trim()).filter(Boolean); }
export const EN_SIZE = () => Object.keys(EN).length;
